const CID=$env.TWITCH_CLIENT_ID, SECRET=$env.TWITCH_CLIENT_SECRET;
const http=this.helpers.httpRequest.bind(this.helpers);
const req=async(url,opt)=>{const r=await http(Object.assign({url},opt));return typeof r==='string'?JSON.parse(r):r;};
const norm=s=>{s=(s||'').toLowerCase().replace(/[™®:\-–]/g,' ').replace(/\b(definitive|complete|game of the year|goty|deluxe|standard|gold|ultimate|remastered)\b/g,'').replace(/\bedition\b/g,'');return s.replace(/\s+/g,' ').trim();};
const GOOD=new Set([0,4,8,9,10,11]),BAD=new Set([1,2,3,5,6,7,13,14]);
const best=(title,cands)=>{const nt=norm(title);let bc=null,bs=-1e9;for(const c of (cands||[])){const nc=norm(c.name||'');let s=c.total_rating_count||0;if(nc===nt)s+=1e5;else if(nc.startsWith(nt)||nt.startsWith(nc))s+=2e4;else if(nc.includes(nt)||nt.includes(nc))s+=5e3;const cat=(c.category==null)?0:c.category;if(GOOD.has(cat))s+=2e3;else if(BAD.has(cat))s-=8e4;if(s>bs){bs=s;bc=c;}}return bc;};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const tok=await http({method:'POST',url:'https://id.twitch.tv/oauth2/token',qs:{client_id:CID,client_secret:SECRET,grant_type:'client_credentials'},json:true});
const H={'Client-ID':CID,'Authorization':'Bearer '+tok.access_token,'Content-Type':'text/plain'};
let games=[];for(const it of $input.all()){if(Array.isArray(it.json))games.push(...it.json);else games.push(it.json);}
const out=[];
for(const g of games){
  const title=String(g.title||'').replace(/"/g,'');
  const e={master_id:g.master_id,enriched_at:new Date().toISOString(),genre:null,release_year:null,length_minutes:null,igdb_id:null,cover_igdb:''};
  try{
    const cands=await req('https://api.igdb.com/v4/games',{method:'POST',headers:H,body:'search "'+title+'"; fields id,name,genres.name,first_release_date,total_rating_count,category,cover.image_id; limit 10;'});
    await sleep(150);
    const m=best(title,cands);
    if(m){
      e.igdb_id=m.id;
      e.cover_igdb=(m.cover&&m.cover.image_id)?m.cover.image_id:'';
      e.genre=(m.genres&&m.genres[0]&&m.genres[0].name)||null;
      e.release_year=m.first_release_date?new Date(m.first_release_date*1000).getUTCFullYear():null;
      try{const ttb=await req('https://api.igdb.com/v4/game_time_to_beats',{method:'POST',headers:H,body:'fields normally; where game_id = '+m.id+';'});if(ttb&&ttb[0]&&ttb[0].normally)e.length_minutes=Math.round(ttb[0].normally/60);}catch(_){}
    }
  }catch(err){e._error=String((err&&err.message)||err).slice(0,140);}
  out.push({json:e});
  await sleep(180);
}
return out;
